function navCount(id){if(id==='incidents')return `<span class="c ${INCIDENTS.some(i=>i.pri==='P1')?'r':''}">${INCIDENTS.filter(i=>i.state!=='Closed').length}</span>`;if(id==='soc')return `<span class="c">${CASES.filter(c=>!c.state.startsWith('Closed')).length}</span>`;if(id==='changes')return `<span class="c">${CHANGES.filter(c=>c.state==='Waiting approval').length}</span>`;return''}
function frame(){const r=ROLES[S.role];document.documentElement.dataset.theme=S.theme;
 $('#app').innerHTML=`<div class="app"><header class="top">
 <button class="btn ic menub" aria-label="Menu" onclick="$('.side').classList.toggle('open')">☰</button>
 <a class="logo" href="#overview"><span class="mk">K<i>.</i></span><span><b>Kirby Operations Hub</b><small>India Global IT Hub</small></span></a>
 <div class="tsp"></div>
 <span class="opby hidesm">Operated by <img src="assets/logos/movate.png" alt="Movate"></span>
 <button class="btn p" onclick="go('demos')"><span class="lbl">Live demos</span><span aria-hidden="true">▶</span></button>
 <button class="btn" onclick="toggleAsk()">Ask Copilot</button>
 <select class="sel hidexs" aria-label="Role" onchange="setRole(this.value)">${Object.entries(ROLES).map(([k,v])=>`<option value="${k}" ${k===S.role?'selected':''}>${v.name}</option>`).join('')}</select>
  <button class="btn ic hidexs" aria-label="Notifications" onclick="showNotif()">🔔${S.notif.length?`<span class="nb">${S.notif.length}</span>`:''}</button>
 <button class="btn ic" aria-label="Light or dark" onclick="setTheme()">${S.theme==='dark'?'☀':'☾'}</button>
 <div class="seg hidesm" role="group" aria-label="Time range">${['live','1h','24h','7d','30d'].map(x=>`<button class="${S.range===x?'on':''}" onclick="S.range='${x}';frame();render()">${x==='live'?'Live':x}</button>`).join('')}</div>
 <div class="seg hidesm" role="group" aria-label="Speed">${[1,5,10].map(x=>`<button class="${S.speed===x?'on':''}" onclick="S.speed=${x};frame();render()">${x}×</button>`).join('')}</div>
 <span class="clock hidesm" id="clock">${hhmmss(S.now)} IST</span></header>
 <nav class="side" aria-label="Main"><div class="who">Signed in as<b>${esc(r.person)}</b>${esc(r.name)}</div>${NAV.map(g=>`<div class="ng">${g[0]}</div>${g[1].map(n=>`<button class="ni ${S.route===n[0]?'on':''}" onclick="go('${n[0]}')">${ico(n[2])}<span>${n[1]}</span>${navCount(n[0])}</button>`).join('')}`).join('')}</nav>
 <div class="mainw"><div class="fbar">Showing <select class="sel" aria-label="Country" onchange="S.country=this.value;S.site='all';render();renderFbar()">${['all',...COUNTRIES].map(c=>`<option value="${c}" ${S.country===c?'selected':''}>${c==='all'?'All countries (6)':c}</option>`).join('')}</select>
 <select class="sel" id="sitesel" aria-label="Site" onchange="S.site=this.value;render();renderFbar()"></select>
 <span class="sum" id="fsum"></span></div><main class="main" id="main"></main>
 <div class="foot">Sample operations data laid over Kirby's captured estate (Infra Capture sheet, NexusNow briefing, Movate proposal v0.3). Estate quantities come from those files; incidents, readings and people are illustrative. Not connected to live tools.</div></div></div>
 <div id="toasts"></div><div id="tip"></div><div id="over"></div>`;renderFbar()}
function renderFbar(){const sel=$('#sitesel');if(sel){const l=SITES.filter(s=>S.country==='all'||s.country===S.country);sel.innerHTML=`<option value="all">All sites (${l.length})</option>`+l.map(s=>`<option value="${s.id}" ${S.site===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}
 const f=$('#fsum');if(f){const c=counts();f.innerHTML=`<span id="syncs" class="syncs">${typeof syncChips==='function'?syncChips():''}</span><span><span class="dot good"></span> ${c.good}</span><span><span class="dot warn"></span> ${c.warn}</span><span><span class="dot bad"></span> ${c.bad}</span><span>${openIncs().length} open incident${openIncs().length===1?'':'s'}</span>`}}
