function heatDomains(){const dom=['Compute','Network','Cloud','Backup / DR','Security','Applications'];let s=`<div class="heat" style="grid-template-columns:78px repeat(24,1fr)"><span></span>`;for(let h=0;h<24;h++)s+=`<span style="text-align:center">${h%6===0?h:''}</span>`;dom.forEach((d,di)=>{s+=`<span>${d}</span>`;for(let h=0;h<24;h++){const v=Math.abs(Math.sin((h+1)*(di+2)*.37))*(h>=8&&h<=19?1:.45);s+=`<i style="opacity:${(.1+v*.9).toFixed(2)}" data-tip="${d}, ${String(h).padStart(2,'0')}:00\n${Math.round(v*42)} alerts"></i>`}});return s+'</div>'}

