 DC.forEach(d=>{const on=trace.includes(d[0]);s+=`<path d="M${HUB.x+30} ${HUB.y}C480 ${HUB.y} 480 ${d[2]} ${d[1]-26} ${d[2]}" fill="none" stroke="${on?'var(--brand)':'var(--line2)'}" stroke-width="${on?3:1.5}"/><path class="flow2" d="M${HUB.x+30} ${HUB.y}C480 ${HUB.y} 480 ${d[2]} ${d[1]-26} ${d[2]}" fill="none" stroke="${on?'var(--brand)':'var(--info)'}" stroke-width="2"/><circle cx="${d[1]}" cy="${d[2]}" r="24" fill="var(--card)" stroke="var(--good)" stroke-width="2.5"/><text x="${d[1]}" y="${d[2]+4}" text-anchor="middle" font-size="9.5" font-weight="650" fill="var(--ink)">${d[0].split(' ')[0]}</text><text x="${d[1]+32}" y="${d[2]+4}" font-size="9.5" fill="var(--ink3)">${d[3].split(',')[0]}</text>`});
